:root {
  --bg: #1a1a2e;
  --surface: #16213e;
  --primary: #e94560;
  --secondary: #0f3460;
  --text: #f0f0f0;
  --card-back: #533483;
  --card-border: #e94560;
  --radius: 8px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-container {
  background: var(--surface);
  border-radius: var(--radius);
  padding: 24px;
  max-width: 640px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

.game-header {
  text-align: center;
  margin-bottom: 24px;
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 8px;
  color: var(--primary);
}

.subtitle {
  font-size: 1rem;
  color: #a0a0b0;
}

.stats {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
  flex-wrap: wrap;
  gap: 12px;
}

.moves {
  font-size: 1.125rem;
  font-weight: 600;
}

.btn {
  background: var(--primary);
  color: #fff;
  border: none;
  border-radius: var(--radius);
  padding: 10px 20px;
  font-size: 1rem;
  font-weight: 600;
  font-family: var(--font);
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

.btn:hover {
  background: #c73651;
}

.btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
}

.board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

.card {
  aspect-ratio: 1 / 1;
  border-radius: var(--radius);
  border: 3px solid var(--card-border);
  background: var(--card-back);
  cursor: pointer;
  position: relative;
  transition: transform 0.2s, background 0.2s;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: 700;
  color: transparent;
  user-select: none;
}

.card:hover:not(.matched) {
  transform: scale(1.05);
}

.card:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.card:active:not(.matched) {
  transform: scale(0.95);
}

.card.flipped {
  background: var(--text);
  color: var(--bg);
  cursor: default;
}

.card.matched {
  background: var(--text);
  color: var(--bg);
  cursor: default;
  border-color: #4caf50;
  opacity: 0.9;
}

.card.matched::after {
  content: '✓';
  font-size: 2rem;
  color: #4caf50;
}

.card.flipped::after,
.card.matched::after {
  content: '';
}

.card.flipped::after {
  content: attr(data-symbol);
}

.win-message {
  margin-top: 24px;
  text-align: center;
  padding: 16px;
  background: var(--secondary);
  border-radius: var(--radius);
  border: 2px solid var(--primary);
  font-size: 1.25rem;
}

.win-message p + p {
  margin-top: 8px;
}

@media (max-width: 480px) {
  .game-container {
    padding: 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .board {
    gap: 8px;
  }
  .card {
    border-width: 2px;
  }
}

@media (max-width: 360px) {
  .board {
    gap: 6px;
  }
  .stats {
    flex-direction: column;
    align-items: stretch;
    text-align: center;
  }
}

(function () {
  'use strict';

  const COLORS = [
    '#e94560', '#533483', '#0f3460', '#f5a623',
    '#4caf50', '#00bcd4', '#ff6f00', '#9c27b0'
  ];

  const boardEl = document.getElementById('board');
  const moveCountEl = document.getElementById('move-count');
  const winMessageEl = document.getElementById('win-message');
  const finalMovesEl = document.getElementById('final-moves');
  const newGameBtn = document.getElementById('new-game');

  let deck = [];
  let flipped = [];
  let matchedPairs = 0;
  let moves = 0;
  let lockBoard = false;

  function shuffle(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
  }

  function createDeck() {
    const cards = [];
    COLORS.forEach((color, idx) => {
      cards.push({ id: idx, color });
      cards.push({ id: idx, color });
    });
    return shuffle(cards);
  }

  function renderBoard() {
    boardEl.innerHTML = '';
    deck.forEach((card, index) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'card';
      btn.dataset.id = card.id;
      btn.dataset.index = index;
      btn.setAttribute('aria-label', 'Card ' + (index + 1) + ', hidden');
      btn.style.backgroundColor = '';
      btn.addEventListener('click', onCardClick);
      boardEl.appendChild(btn);
    });
  }

  function onCardClick(e) {
    const card = e.currentTarget;
    if (lockBoard || card.classList.contains('flipped') || card.classList.contains('matched')) {
      return;
    }

    card.classList.add('flipped');
    card.style.backgroundColor = deck[card.dataset.index].color;
    card.setAttribute('aria-label', 'Card ' + (Number(card.dataset.index) + 1) + ', revealed');
    flipped.push(card);

    if (flipped.length === 2) {
      moves++;
      moveCountEl.textContent = moves;
      checkMatch();
    }
  }

  function checkMatch() {
    const [a, b] = flipped;
    if (a.dataset.id === b.dataset.id) {
      a.classList.add('matched');
      b.classList.add('matched');
      a.setAttribute('aria-label', 'Card matched');
      b.setAttribute('aria-label', 'Card matched');
      flipped = [];
      matchedPairs++;
      if (matchedPairs === COLORS.length) {
        winGame();
      }
    } else {
      lockBoard = true;
      setTimeout(() => {
        a.classList.remove('flipped');
        b.classList.remove('flipped');
        a.style.backgroundColor = '';
        b.style.backgroundColor = '';
        a.setAttribute('aria-label', 'Card ' + (Number(a.dataset.index) + 1) + ', hidden');
        b.setAttribute('aria-label', 'Card ' + (Number(b.dataset.index) + 1) + ', hidden');
        flipped = [];
        lockBoard = false;
      }, 800);
    }
  }

  function winGame() {
    finalMovesEl.textContent = moves;
    winMessageEl.hidden = false;
  }

  function resetGame() {
    deck = createDeck();
    flipped = [];
    matchedPairs = 0;
    moves = 0;
    lockBoard = false;
    moveCountEl.textContent = '0';
    winMessageEl.hidden = true;
    renderBoard();
  }

  newGameBtn.addEventListener('click', resetGame);
  resetGame();
})();
